{"version":"v0.9","updateComponents":{"surfaceId":"team-settings","components":[{"id":"root","component":"Stack","gap":"lg","children":["appbar","content"]},{"id":"appbar","component":"AppBar","title":"Team settings","subtitle":{"path":"/team/name"}},{"id":"content","component":"Stack","gap":"lg","style":{"padding":"$spacing.lg","maxWidth":"720px","width":"100%","marginHorizontal":"auto"},"children":["general-card","danger-card"]},{"id":"general-card","component":"Card","title":"General","description":"How your team appears across the workspace.","children":["general-form"]},{"id":"general-form","component":"Form","name":"teamGeneral","busy":{"path":"/saving"},"on":{"submit":{"event":{"name":"saveTeamSettings","context":{"name":{"path":"/team/name"},"slug":{"path":"/team/slug"},"timezone":{"path":"/team/timezone"}}}}},"children":["name-input","slug-input","slug-preview","tz-select","form-actions"]},{"id":"name-input","component":"Input","label":"Team name","name":"name","value":{"path":"/team/name"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/team/name"}}},"message":"Enter a team name."},{"condition":{"call":"length","args":{"value":{"path":"/team/name"},"min":2,"max":48}},"message":"Use 2 to 48 characters."}]},{"id":"slug-input","component":"Input","label":"URL slug","name":"slug","value":{"path":"/team/slug"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/team/slug"}}},"message":"Enter a URL slug."},{"condition":{"call":"regex","args":{"value":{"path":"/team/slug"},"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$"}},"message":"Use lowercase letters, numbers and single hyphens."},{"condition":{"call":"length","args":{"value":{"path":"/team/slug"},"min":3,"max":32}},"message":"Use 3 to 32 characters."}]},{"id":"slug-preview","component":"Text","variant":"muted","text":{"call":"concat","args":{"values":["app.exponential.at/",{"path":"/team/slug"}]}}},{"id":"tz-select","component":"Select","label":"Timezone","name":"timezone","searchabl